package com.wipro.hibernate;import java.math.BigDecimal;public class Product{private int productId;private String productName;private BigDecimal price;public Product(){}public int getProductId(){return productId;}public void setProductId(int v){productId=v;}public String getProductName(){return productName;}public void setProductName(String v){productName=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}}